[{"order":1,"type":"heading","text":"Hibernate Envers for Auditing"},{"order":2,"type":"paragraph","text":"Hibernate Envers is a powerful module that provides an easy auditing solution for your persistent entities. It tracks all changes made to your domain model, automatically generating historical tables and maintaining a complete history of revisions without requiring manual logging logic."},{"order":3,"type":"subheading","text":"Key Concepts in Hibernate Envers"},{"order":4,"type":"bullet_point","text":"Entity Versioning: Every time an audited entity is inserted, updated, or deleted, a new row is created in a corresponding audit table."},{"order":5,"type":"bullet_point","text":"Revision Entity: Envers tracks the transaction or revision timestamp using a revision entity, often linked to the user performing the action."},{"order":6,"type":"bullet_point","text":"Audit Tables: By default, Envers appends "_AUD" to the original table name to store historical data."},{"order":7,"type":"subheading","text":"Step 1: Add Dependencies"},{"order":8,"type":"paragraph","text":"To get started, include the Hibernate Envers dependency in your project. For Maven, add the following artifact to your pom.xml file:"},{"order":9,"type":"code","text":"<dependency>
    <groupId>org.hibernate</groupId>
    <artifactId>hibernate-envers</artifactId>
</dependency>"},{"order":10,"type":"subheading","text":"Step 2: Annotate Entities"},{"order":11,"type":"paragraph","text":"To enable auditing for an entity, simply annotate the class with the @Audited annotation. You can also exclude specific fields using @NotAudited."},{"order":12,"type":"code","text":"import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.Id;
import org.hibernate.envers.Audited;
import org.hibernate.envers.NotAudited;

@Entity
@Audited
public class User {

    @Id
    @GeneratedValue
    private Long id;

    private String username;

    @NotAudited
    private String temporaryToken;

    // Getters and setters
}"},{"order":13,"type":"subheading","text":"Step 3: Querying Audit History"},{"order":14,"type":"paragraph","text":"Hibernate Envers provides the AuditReader API, which allows you to query historical data easily. You can retrieve revisions for a specific entity ID as shown below:"},{"order":15,"type":"code","text":"import jakarta.persistence.EntityManager;
import org.hibernate.envers.AuditReader;
import org.hibernate.envers.AuditReaderFactory;

public class AuditService {

    private EntityManager entityManager;

    public AuditService(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    public void printUserRevisions(Long userId) {
        AuditReader auditReader = AuditReaderFactory.get(entityManager);
        List<Number> revisions = auditReader.getRevisions(User.class, userId);

        for (Number revision : revisions) {
            User userAtRevision = auditReader.find(User.class, userId, revision);
            System.out.println("Revision: " + revision + ", Username: " + userAtRevision.getUsername());
        }
    }
}"},{"order":16,"type":"subheading","text":"Conclusion"},{"order":17,"type":"paragraph","text":"Hibernate Envers simplifies the implementation of data auditing with minimal configuration. By using @Audited and the AuditReader API, developers can track application data changes efficiently and reliably."}]
